import { cn } from "@/lib/utils";
import { motion } from "motion/react";
import Image from "next/image";
import { PropsWithChildren } from "react";

const MotionImage = motion(Image);

type Props = PropsWithChildren<{
  src: string;
  alt: string;
  width: number;
  height: number;
  className?: string;
  imageClassName?: string;
}>;

export default function Portrait({ src, alt, width, height, className, imageClassName }: Props) {
  const mergedClassName = cn(
    'relative rounded-full overflow-hidden',
    className
  );

  const mergedImageClassName = cn(
    'z-0',
    imageClassName
  );

  return (
    <div className={mergedClassName}>
      <MotionImage priority src={src} alt={alt} width={width} height={height} className={mergedImageClassName} />
    </div>
  );
}